SET NAMES utf8mb4;
USE `merchant_db`;

ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `sort_order` = VALUES(`sort_order`);

ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `phone` = VALUES(`phone`), `address` = VALUES(`address`), `longitude` = VALUES(`longitude`), `latitude` = VALUES(`latitude`), `business_hours` = VALUES(`business_hours`), `category` = VALUES(`category`), `description` = VALUES(`description`), `avatar` = VALUES(`avatar`), `tags` = VALUES(`tags`), `status` = VALUES(`status`), `rating` = VALUES(`rating`), `monthly_sales` = VALUES(`monthly_sales`), `min_delivery_fee` = VALUES(`min_delivery_fee`), `delivery_fee` = VALUES(`delivery_fee`), `delivery_radius` = VALUES(`delivery_radius`);

ON DUPLICATE KEY UPDATE `merchant_id` = VALUES(`merchant_id`), `category_id` = VALUES(`category_id`), `name` = VALUES(`name`), `image` = VALUES(`image`), `price` = VALUES(`price`), `description` = VALUES(`description`), `monthly_sales` = VALUES(`monthly_sales`), `stock` = VALUES(`stock`), `type` = VALUES(`type`), `status` = VALUES(`status`), `gallery` = VALUES(`gallery`);

ON DUPLICATE KEY UPDATE `product_id` = VALUES(`product_id`), `name` = VALUES(`name`), `values` = VALUES(`values`);

ON DUPLICATE KEY UPDATE `product_id` = VALUES(`product_id`), `label` = VALUES(`label`), `price` = VALUES(`price`), `stock` = VALUES(`stock`);

SELECT COUNT(*) AS hpa_demo_merchants FROM `merchant` WHERE `id` >= 900000;
SELECT COUNT(*) AS hpa_demo_products FROM `product` WHERE `id` >= 910000;

